import React from 'react';
import ReactDOM from 'react-dom';
import TodoList from './TodoList';

class TodoListApp extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      todos: [
        { id: 1, name: 'Buy milk', completed: false },
        { id: 2, name: 'Do laundry', completed: false },
        { id: 3, name: 'Walk the dog', completed: false },
      ],
      newTodo: '',
    };
  }

  handleSubmit = (event) => {
    event.preventDefault();
    const newTodo = this.state.newTodo.trim();
    if (newTodo !== '') {
      this.setState({
        todos: [...this.state.todos, { id: this.state.todos.length + 1, name: newTodo, completed: false }],
        newTodo: '',
      });
    }
  };

  handleToggle = (id) => {
    this.setState({
      todos: this.state.todos.map((todo) => {
        if (todo.id === id) {
          todo.completed = !todo.completed;
        }
        return todo;
      }),
    });
  };

  handleDelete = (id) => {
    this.setState({
      todos: this.state.todos.filter((todo) => todo.id !== id),
    });
  };

  render() {
    return (
      <div>
        <form onSubmit={this.handleSubmit}>
          <input type="text" value={this.state.newTodo} onChange={(event) => this.setState({ newTodo: event.target.value })} />
          <button type="submit">Add Todo</button>
        </form>
        <ul>
          {this.state.todos.map((todo) => (
            <li key={todo.id}>
              <input type="checkbox" checked={todo.completed} onChange={() => this.handleToggle(todo.id)} />
              <span style={{ textDecoration: todo.completed ? 'line-through' : 'none' }}>{todo.name}</span>
              <button onClick={() => this.handleDelete(todo.id)}>Delete</button>
            </li>
          ))}
        </ul>
      </div>
    );
  }
}

ReactDOM.render(<TodoListApp />, document.getElementById('root'));
